mapper.update:
update signal_window_state
set is_active = false
where symbol = #{symbol}
  and is_active = true
  and expires_at is not null
  and expires_at < #{currentTime}

mapper.select:
select dr.id, dr.trace_id as traceId, dr.symbol, dr.mode, dr.action, dr.confidence, dr.summary_reason as summaryReason, dr.model_code as modelCode, dr.model_provider as modelProvider, dr.prompt_source as promptSource, dr.binding_template_code as bindingTemplateCode, dr.fallback_template_code as fallbackTemplateCode, dr.resolved_template_code as resolvedTemplateCode, dr.prompt_template_fallback_used as promptTemplateFallbackUsed, dr.trigger_reason as triggerReason, dr.trigger_source as triggerSource, dr.dispatch_mode as dispatchMode, dr.selected_agents_json as selectedAgentsJson, dr.combination_match_json as combinationMatchJson, dr.active_signal_refs_json as activeSignalRefsJson, dr.cooldown_blocked as cooldownBlocked, dr.budget_blocked as budgetBlocked, as executionStatus, coalesce(dr.order_status, eo.order_status) as orderStatus, dr.created_at as createdAt from decision_run dr left join ( select trace_id, max(id) as latest_id from exchange_order group by trace_id ) latest_eo on latest_eo.trace_id = dr.trace_id left join exchange_order eo on eo.id = latest_eo.latest_id
= #{executionStatus}
and
coalesce(dr.order_status, eo.order_status) = #{orderStatus}
order by dr.id desc

select eo.id, eo.trace_id as traceId, eo.status, eo.order_status as orderStatus, eo.created_at as createdAt from exchange_order eo inner join ( select trace_id, max(id) as latest_id from exchange_order where trace_id in
#{traceId}
group by trace_id ) latest on latest.latest_id = eo.id order by eo.id desc

select fs.id, fs.trace_id as traceId, fs.symbol, fs.event_strength as eventStrength, fs.snapshot_json as snapshotJson, fs.created_at as createdAt from feature_snapshot fs inner join ( select trace_id, max(id) as max_id from feature_snapshot where trace_id in
#{traceId}
group by trace_id ) latest on latest.max_id = fs.id order by fs.id desc

select am.id, am.trace_id as traceId, am.agent_run_id as agentRunId, am.round_no as roundNo, am.speaker_agent as speakerAgent, am.target_agent as targetAgent, am.message_type as messageType, am.template_code as templateCode, am.model_code as modelCode, am.content_json as contentJson, am.summary_text as summaryText, am.created_at as createdAt from agent_message am where am.trace_id in
#{traceId}
order by am.trace_id desc, am.round_no asc, am.id asc

select am.id, am.trace_id as traceId, am.agent_run_id as agentRunId, am.round_no as roundNo, am.speaker_agent as speakerAgent, am.target_agent as targetAgent, am.message_type as messageType, am.template_code as templateCode, am.model_code as modelCode, am.content_json as contentJson, am.summary_text as summaryText, am.created_at as createdAt from agent_message am inner join decision_run dr on dr.trace_id = am.trace_id where upper(dr.symbol) = upper(#{symbol})
and upper(dr.mode) = upper(#{mode})
and am.speaker_agent = 'supervisor_agent' and am.message_type = 'final_decision'
and am.trace_id != #{excludeTraceId}
order by am.created_at desc, am.id desc limit #{limit}

select dr.id, dr.trace_id as traceId, dr.symbol, dr.mode, dr.action, dr.confidence, dr.summary_reason as summaryReason, dr.model_code as modelCode, dr.model_provider as modelProvider, dr.prompt_source as promptSource, dr.binding_template_code as bindingTemplateCode, dr.fallback_template_code as fallbackTemplateCode, dr.resolved_template_code as resolvedTemplateCode, dr.prompt_template_fallback_used as promptTemplateFallbackUsed, dr.trigger_reason as triggerReason, dr.trigger_source as triggerSource, dr.dispatch_mode as dispatchMode, dr.selected_agents_json as selectedAgentsJson, dr.combination_match_json as combinationMatchJson, dr.active_signal_refs_json as activeSignalRefsJson, dr.cooldown_blocked as cooldownBlocked, dr.budget_blocked as budgetBlocked, dr.execution_status as executionStatus, dr.order_status as orderStatus, dr.created_at as createdAt from decision_run dr where upper(dr.symbol) = upper(#{symbol})
and upper(dr.mode) = upper(#{mode})
and dr.trace_id != #{excludeTraceId}
order by dr.created_at desc, dr.id desc limit #{limit}
